// The types of rueder's API: what the server sends and reads as JSON.
//
// Written out of the Rust types in server/src/. Do not edit this file: change
// the type there and run `UPDATE_API_TYPES=1 cargo test --test api_types` in
// server/. The same test fails in CI when this file is out of date.
//
// Times are strings as in RFC 3339, such as "2026-11-11T10:08:37Z". A field
// with `?` may be left out of a request. Errors come as plain text, not JSON.

/**
 * What `GET /api/health` answers.
 */
export type Health = {
	status: string,
	feeds: number,
};

/**
 * What `POST /api/login` reads. It answers with `Me` and sets the session's
 * cookie. An account with a second factor needs `code` too, from the app or
 * a recovery code; without it, the answer is 401 with `second factor needed`.
 */
export type Credentials = {
	username: string,
	password: string,
	code?: string,
};

/**
 * Who is logged in, as the API says it.
 *
 * `GET /api/me` and `POST /api/login` answer with it.
 */
export type Me = {
	id: number,
	username: string,
	is_admin: boolean,
	/**
	 * Whether the account has a password, which deleting it asks for. One
	 * that logs in only through OpenID Connect has none.
	 */
	has_password: boolean,
	/**
	 * An admin whose right waits for a login with a second factor, where the
	 * server wants one of admins.
	 */
	admin_needs_second_factor: boolean,
	/**
	 * The version of the terms of use the account has yet to agree to, where
	 * the server names one; the page asks before anything else.
	 */
	terms_to_accept: string | null,
	/**
	 * Whether the account may report feeds and articles on this server.
	 */
	content_reports: boolean,
	/**
	 * Whether apps of other makers may log in to this server with app
	 * passwords.
	 */
	app_api: boolean,
};

/**
 * The ways to log in this server has besides name and password.
 *
 * `GET /api/login/ways` answers with it, to anybody.
 */
export type LoginWays = {
	/**
	 * Through the OpenID Connect provider, at `/api/oidc/start`.
	 */
	oidc: boolean,
	/**
	 * Anybody can make an account for themselves, at `/api/register`.
	 */
	registration: boolean,
	/**
	 * The operator's legal texts, for the login page to link to.
	 */
	legal: LegalLinks,
};

/**
 * Where the operator's texts are, and which version of the terms counts.
 *
 * `GET /api/login/ways` answers with it, to anybody.
 */
export type LegalLinks = {
	imprint: string | null,
	privacy: string | null,
	terms: string | null,
	/**
	 * The version of the terms an account has to agree to; none if nobody
	 * has to.
	 */
	terms_version: string | null,
};

/**
 * One place a reader is logged in.
 *
 * `GET /api/sessions` answers with a list of them; `DELETE /api/sessions/{id}`
 * ends one, `DELETE /api/sessions` all but the one that asks.
 */
export type Device = {
	/**
	 * A name for the session that is not its token and leads to none.
	 */
	id: string,
	created_at: string,
	last_seen_at: string,
	/**
	 * The session that asks.
	 */
	current: boolean,
};

/**
 * What `PUT /api/password` reads.
 */
export type NewPassword = {
	/**
	 * The password so far. An account that has none needs none.
	 */
	current?: string,
	new: string,
};

/**
 * What `DELETE /api/account` reads: proof that the reader means it.
 */
export type Farewell = {
	/**
	 * The account's password. An account that has none sends its name.
	 */
	password?: string,
	name?: string,
	/**
	 * A code of the app or a recovery code, where the second factor is on.
	 */
	code?: string,
};

/**
 * An account as an admin sees it.
 *
 * `GET /api/accounts` answers with a list of them, for admins only.
 */
export type Account = {
	id: number,
	username: string,
	is_admin: boolean,
	has_password: boolean,
	/**
	 * Disabled by the operator, with `rueder account disable`.
	 */
	disabled: boolean,
	created_at: string,
};

/**
 * What `POST /api/accounts` reads, for admins only. It answers with `Created`.
 */
export type NewAccount = {
	username: string,
	/**
	 * The first password, which the admin hands over and the reader changes.
	 */
	password: string,
	is_admin?: boolean,
};

/**
 * The answer to making something: the number it got.
 */
export type Created = {
	id: number,
};

/**
 * Whether an account has the second factor, and how many recovery codes it
 * has left.
 *
 * `GET /api/second-factor` answers with it.
 */
export type SecondFactor = {
	on: boolean,
	recovery_codes_left: number,
	/**
	 * Whether this server lets admins be admins only with it.
	 */
	required_for_admins: boolean,
};

/**
 * What setting up reads: the password of the account. An account that has
 * none needs none.
 */
export type SecondFactorPassword = {
	password?: string,
};

/**
 * What switching off reads: the password, as for setting up, and a code from
 * the app or a recovery code.
 */
export type SecondFactorSwitchOff = {
	password?: string,
	code: string,
};

/**
 * A new secret for the app, waiting for a code to confirm it.
 *
 * `POST /api/second-factor/setup` answers with it.
 */
export type SecondFactorSetup = {
	/**
	 * The secret in base32, to type into an app by hand.
	 */
	secret: string,
	/**
	 * The `otpauth://` address apps read from the QR code.
	 */
	uri: string,
	/**
	 * The QR code of `uri`, as SVG.
	 */
	qr_svg: string,
};

/**
 * A code from the app.
 *
 * `POST /api/second-factor/confirm` reads it.
 */
export type SecondFactorCode = {
	code: string,
};

/**
 * The recovery codes, shown once.
 *
 * `POST /api/second-factor/confirm` answers with them.
 */
export type RecoveryCodes = {
	codes: Array<string>,
};

/**
 * The version of the terms the reader agrees to.
 *
 * `PUT /api/terms` reads it.
 */
export type TermsAgreement = {
	version: string,
};

/**
 * A report of a feed or an article.
 *
 * `POST /api/feeds/{id}/report` and `POST /api/feeds/{id}/articles/{seq}/report`
 * read it and answer 204.
 */
export type ContentReport = {
	reason: ReportReason,
	/**
	 * What the reader adds, at most 500 characters.
	 */
	note?: string,
};

/**
 * Why something is reported.
 */
export type ReportReason = "illegal" | "copyright" | "malicious" | "spam" | "other";

/**
 * A feed readers reported, for the status page: its address, never who.
 */
export type ReportedFeed = {
	feed_id: number,
	url: string,
	title: string,
	reports: number,
	/**
	 * How many reports gave each reason, the most first.
	 */
	reasons: Array<ReportReasonCount>,
	last_at: string,
	blocked: boolean,
};

export type ReportReasonCount = {
	reason: ReportReason,
	reports: number,
};

/**
 * What `GET /api/app-passwords` answers.
 */
export type AppPasswords = {
	app_passwords: Array<AppPassword>,
	/**
	 * How many the account can have.
	 */
	max: number,
};

/**
 * An app password as the list shows it: never the password itself.
 */
export type AppPassword = {
	id: number,
	name: string,
	created_at: string,
	/**
	 * When an app last logged in with it, to the hour; null until one did.
	 */
	used_at: string | null,
};

/**
 * What `POST /api/app-passwords` reads: a name for it, and the account's
 * password and, where the second factor is on, one of its codes.
 */
export type NewAppPassword = {
	name: string,
	password?: string,
	code?: string,
};

/**
 * What `POST /api/app-passwords` answers: the app password, this once.
 */
export type CreatedAppPassword = {
	/**
	 * In groups of four letters, as it is shown to be typed.
	 */
	secret: string,
	id: number,
	name: string,
	created_at: string,
	/**
	 * When an app last logged in with it, to the hour; null until one did.
	 */
	used_at: string | null,
};

/**
 * The query of `GET /api/register`.
 */
export type AskedInvite = {
	/**
	 * The token of an invitation to ask about.
	 */
	invite?: string,
};

/**
 * What the page for registering needs to know before anybody typed a name.
 *
 * `GET /api/register` answers with it, to anybody; with `?invite=<token>` it
 * also says whether that invitation can be used.
 */
export type Registering = {
	/**
	 * Anybody can register, and there is room.
	 */
	open: boolean,
	/**
	 * Whether the invitation that was asked about is good: known, not taken
	 * back, not run out, not used up. Left out if none was asked about.
	 */
	invite?: boolean,
};

/**
 * What `POST /api/register` reads. It answers with `Me` and sets the
 * session's cookie, as a login does.
 *
 * A refusal is 403 with one word: `terms` (the terms of use the server names
 * were not agreed to), `closed` (no invitation, and registration is not open),
 * `invite` (the invitation cannot be used), `full` (no room for another
 * account) or `today` (enough accounts for one day). A name or a
 * password that cannot be one is 400 with the reason, a name that is taken
 * 409.
 */
export type NewRegistration = {
	username: string,
	password: string,
	/**
	 * The token of an invitation.
	 */
	invite?: string,
	/**
	 * The version of the terms of use agreed to, where the server names one.
	 */
	accepted_terms?: string,
};

/**
 * An invitation as the one who made it sees it. The link itself is shown
 * once, when it is made.
 */
export type Invite = {
	id: number,
	/**
	 * For how many accounts it is, and how many it brought.
	 */
	max_uses: number,
	uses: number,
	created_at: string,
	expires_at: string,
	revoked: boolean,
	/**
	 * It can still be used: not taken back, not run out, not used up.
	 */
	usable: boolean,
};

/**
 * The reader's invitations and how many more they can make.
 *
 * `GET /api/invites` answers with it.
 */
export type Invites = {
	/**
	 * The newest first.
	 */
	invites: Array<Invite>,
	/**
	 * For how many more accounts the reader can make invitations. Left out
	 * for an admin, who has no quota.
	 */
	left?: number,
	/**
	 * How many days a new invitation is good for.
	 */
	days: number,
};

/**
 * What `POST /api/invites` reads. It answers with `MadeInvite`.
 */
export type NewInvite = {
	/**
	 * For how many accounts the link is; one if left out.
	 */
	uses?: number,
};

/**
 * A new invitation, with its token, which is never shown again. The link is
 * the page's address with `?invite=<token>`.
 */
export type MadeInvite = {
	id: number,
	token: string,
	expires_at: string,
};

/**
 * What `GET /api/tree` answers: the account's folders and subscriptions, each
 * as a plain list. `parent_id` and `folder_id` say what lies where, `position`
 * in which order.
 */
export type Tree = {
	folders: Array<Folder>,
	feeds: Array<Feed>,
	/**
	 * How many articles the account's rules hide, for the list of them.
	 */
	hidden: number,
};

/**
 * A subscription with what the tree shows of its feed.
 *
 * `folder_id` is the folder it lies in, null at the top.
 */
export type Feed = {
	id: number,
	folder_id: number | null,
	position: number,
	/**
	 * The name the reader gave it, else the feed's own, else, for a feed
	 * that has none (yet), the host of its address.
	 */
	title: string,
	feed_title: string,
	feed_url: string,
	site_url: string | null,
	icon_url: string | null,
	fetch_agent: FetchAgent,
	/**
	 * Why the last fetch failed, if it did.
	 */
	error: string | null,
	/**
	 * Whether the feed was fetched at all yet. One that came with an OPML
	 * file waits for the next round.
	 */
	fetched: boolean,
	/**
	 * The operator blocked the feed: nobody sees its articles, and it is not
	 * fetched.
	 */
	blocked: boolean,
	last_seq: number,
	read_upto: number,
	unread: number,
};

/**
 * Who a feed is fetched as: as rueder, or as a browser, for sites that turn
 * readers like rueder away.
 */
export type FetchAgent = "rueder" | "browser";

/**
 * A folder of the tree. `parent_id` is the folder it lies in, null at the top.
 */
export type Folder = {
	id: number,
	parent_id: number | null,
	title: string,
	position: number,
};

/**
 * Which part of a list is asked for.
 *
 * The query of every list: `GET /api/articles`, `/api/starred`, `/api/hidden`,
 * `/api/feeds/{id}/articles`, `/api/folders/{id}/articles` and
 * `/api/labels/{id}/articles`. Each answers with `List`.
 */
export type ListQuery = {
	/**
	 * Only what arrived before the article of this `id`.
	 */
	before?: number,
	/**
	 * Only what arrived after the article of this `id`, the oldest first; 0
	 * starts at the oldest article there is. Not together with `before`.
	 */
	after?: number,
	limit?: number,
	/**
	 * Leave out what was read.
	 */
	unread?: boolean,
};

/**
 * A page of a list, the newest article first. For the next page, ask again
 * with `before` set to the `id` of the last article of this one. A list asked
 * for with `after` has the oldest article first and goes on the same way,
 * with `after`.
 */
export type List = {
	articles: Array<ListItem>,
};

/**
 * What was different about an article when it last got a new version. A feed
 * that only rewrites a headline says nothing in the text, and the reader would
 * look for a change in vain.
 */
export type Changed = "title" | "text" | "both";

/**
 * A line of a list, with the labels the reader gave the article.
 */
export type ListItem = {
	labels: Array<number>,
	feed_id: number,
	seq: number,
	/**
	 * Where the article stands in the order of arrival; the anchor for the next page.
	 */
	id: number,
	published_at: string,
	/**
	 * When the current version replaced the one before, if it ever did.
	 */
	updated_at: string | null,
	/**
	 * What was different then; null for a change from before rueder noted it.
	 */
	updated_what: Changed | null,
	version: number,
	title: string,
	teaser: string,
	author: string,
	url: string | null,
	thumbnail_url: string | null,
	read: boolean,
	starred: boolean,
};

/**
 * An article for reading, with the labels the reader gave it.
 *
 * `GET /api/feeds/{id}/articles/{seq}` answers with it.
 */
export type Article = {
	enclosures: Array<Enclosure>,
	labels: Array<number>,
	/**
	 * The rule that hides the article, if one does: the first of the
	 * account's rules that would, in their order.
	 */
	hidden_by: number | null,
	feed_id: number,
	seq: number,
	id: number,
	published_at: string,
	updated_at: string | null,
	/**
	 * What was different then; null for a change from before rueder noted it.
	 */
	updated_what: Changed | null,
	version: number,
	title: string,
	author: string,
	url: string | null,
	html: string,
	tags: Array<string>,
	image_url: string | null,
	image_title: string | null,
};

/**
 * A file that comes with an article, like the episode of a podcast.
 */
export type Enclosure = {
	url: string,
	/**
	 * Its media type, such as `audio/mpeg`, if the feed says.
	 */
	type: string | null,
	/**
	 * Its size in bytes, if the feed says.
	 */
	length: number | null,
	/**
	 * It stood in the article's text and not in the feed's own list.
	 */
	inline: boolean,
};

/**
 * What `GET /api/feeds/{id}/articles/{seq}/versions` answers: the versions of
 * the article that are kept, oldest first.
 */
export type Versions = {
	versions: Array<ArticleVersion>,
};

/**
 * One version of an article, cleaned for reading like the current one.
 */
export type ArticleVersion = {
	version: number,
	fetched_at: string,
	title: string,
	html: string,
	authors: Array<string>,
	tags: Array<string>,
	url: string | null,
};

/**
 * What to change about one article; what is left out stays.
 *
 * What `PUT /api/feeds/{id}/articles/{seq}/state` reads.
 */
export type StateChange = {
	read?: boolean | null,
	starred?: boolean | null,
};

/**
 * How far to mark as read: up to a number in the feed, or up to the article
 * of this `id` in the order of arrival, which is what a mixed list knows.
 * With `older_than`, only what was published more than that many seconds
 * ago.
 *
 * What `POST /api/feeds/{id}/read`, `/api/folders/{id}/read` and `/api/read`
 * read.
 */
export type Upto = {
	upto?: number | null,
	upto_id?: number | null,
	older_than?: number | null,
};

/**
 * A search through the articles of the account's feeds: `GET /api/search`.
 * Answers with `SearchHits`.
 */
export type SearchQuery = {
	/**
	 * The words. An article is found if it has all of them in its title, its
	 * author, its tags or its text; a word of three letters or more also
	 * finds the words that begin with it.
	 */
	q: string,
	/**
	 * Only in this feed.
	 */
	feed?: number,
	/**
	 * Only in the feeds of this folder and the folders inside it. Not
	 * together with `feed`.
	 */
	folder?: number,
	/**
	 * Only what arrived before this `id`: `next` of the page before.
	 */
	before?: number,
	limit?: number,
	/**
	 * Leave out what was read.
	 */
	unread?: boolean,
};

/**
 * A page of what a search found, the newest first.
 */
export type SearchHits = {
	articles: Array<ListItem>,
	/**
	 * Where the next page begins, as `before`; null if nothing older is
	 * left. A page can hold fewer articles than asked for, even none, and
	 * still have a `next`: the server searches for so long per request.
	 */
	next: number | null,
};

/**
 * Where a node goes, seen from the node it is dropped on, as in the
 * interface's own model of the tree.
 *
 * What `POST /api/tree/move` reads.
 */
export type Move = {
	node: NodeRef,
	target: NodeRef,
	position: DropPosition,
};

/**
 * The side of the node it is dropped on that a node lands on: before it,
 * after it or, for a folder, inside it.
 */
export type DropPosition = "before" | "after" | "inside";

/**
 * A folder or a subscription, as the tree's changes name them.
 */
export type NodeRef =
	| {
		"kind": "folder",
		"id": number,
	}
	| {
		"kind": "feed",
		"id": number,
	};

/**
 * What `POST /api/folders` reads. It answers with `Created`.
 */
export type NewFolder = {
	title: string,
	parent_id?: number | null,
};

/**
 * What `PATCH /api/folders/{id}` and `PATCH /api/feeds/{id}` read. A
 * subscription without a title of its own goes by its feed's.
 */
export type Rename = {
	title?: string | null,
};

/**
 * What `PUT /api/feeds/{id}/agent` reads.
 */
export type NewAgent = {
	agent: FetchAgent,
};

/**
 * What `POST /api/feeds/find` reads: the address of a feed or of a page that
 * names its feeds.
 */
export type FindFeeds = {
	url: string,
};

/**
 * What `POST /api/feeds/find` answers.
 */
export type FoundFeeds = {
	feeds: Array<FeedCandidate>,
	/**
	 * Where the site sent the request on to, if it did: a site that turns
	 * readers away often sends them to its login.
	 */
	moved_to: string | null,
};

/**
 * A feed found at an address.
 */
export type FeedCandidate = {
	url: string,
	title: string,
	/**
	 * The number of the feed if the reader subscribes to it already.
	 */
	feed_id: number | null,
};

/**
 * What `POST /api/feeds` reads. It answers with `Subscribed`.
 */
export type NewSubscription = {
	url: string,
	folder_id?: number | null,
};

/**
 * The answer to subscribing: the number of the feed.
 */
export type Subscribed = {
	id: number,
};

/**
 * What an import did.
 *
 * `POST /api/opml` answers with it; the request is the file itself.
 */
export type OpmlImported = {
	/**
	 * Feeds the account reads now and did not before.
	 */
	feeds: number,
	/**
	 * Folders that were made.
	 */
	folders: number,
	/**
	 * Feeds of the file the account read already.
	 */
	known: number,
	/**
	 * Outlines that were left out, see [`Outline::skipped`].
	 */
	skipped: number,
};

/**
 * A label. `GET /api/labels` answers with a list of them.
 */
export type Label = {
	id: number,
	title: string,
	color: string,
	position: number,
};

/**
 * What `POST /api/labels` reads. It answers with `Created`.
 */
export type NewLabel = {
	title: string,
	color: string,
};

/**
 * What to change about a label; what is left out stays.
 *
 * What `PATCH /api/labels/{id}` reads.
 */
export type LabelChange = {
	title?: string | null,
	color?: string | null,
};

/**
 * A new order: every number once, in the order they shall stand in.
 */
export type Order = {
	ids: Array<number>,
};

/**
 * A rule as the API takes and gives it.
 *
 * `GET /api/rules` answers with a list of them. `POST /api/rules`,
 * `PUT /api/rules/{id}` and `POST /api/rules/preview` read one; there the `id`
 * counts for nothing, and a rule without `enabled` is enabled.
 */
export type Rule = {
	id: number,
	enabled: boolean,
	scope: RuleScope,
	field: RuleField,
	match: RuleMatch,
	pattern: string,
	action: RuleAction,
};

/**
 * What a rule does with an article it matches.
 */
export type RuleAction = "hide" | "read";

/**
 * The part of an article a rule looks at.
 */
export type RuleField = "any" | "title" | "content" | "author" | "tag";

/**
 * How a rule's pattern is read: as text that stands anywhere, as a whole
 * word, or as a regular expression.
 */
export type RuleMatch = "contains" | "word" | "regex";

/**
 * Where a rule holds: everywhere, in a folder with all that is in it, or in
 * one feed.
 */
export type RuleScope =
	| {
		"kind": "all",
	}
	| {
		"kind": "folder",
		"id": number,
	}
	| {
		"kind": "feed",
		"id": number,
	};

/**
 * What a change to the rules did to the articles that are there.
 *
 * `POST /api/rules`, `PUT` and `DELETE /api/rules/{id}` answer with it.
 */
export type RuleOutcome = {
	id: number,
	changed: RuleChanged,
};

/**
 * What a look at the articles changed.
 */
export type RuleChanged = {
	/**
	 * Articles that are hidden now and were not.
	 */
	hidden: number,
	/**
	 * Articles that were hidden and are back.
	 */
	shown: number,
	/**
	 * Articles marked read.
	 */
	read: number,
};

/**
 * How many articles a rule would catch.
 *
 * What `POST /api/rules/preview` answers.
 */
export type RulePreview = {
	/**
	 * The articles the rule matches,
	 */
	matches: number,
	/**
	 * of this many it looked at: the newest of each feed in its scope.
	 */
	of: number,
};

/**
 * What `GET /api/rules/hits` answers: for every rule of the account what it
 * finds among the articles that are there, as a preview of it would say.
 */
export type RulesHits = {
	hits: Array<RuleHits>,
};

/**
 * What one of the stored rules finds.
 */
export type RuleHits = {
	id: number,
	/**
	 * The articles the rule matches, whether it is switched on or not,
	 */
	matches: number,
	/**
	 * of this many it looked at: the newest of each feed in its scope.
	 */
	of: number,
};

/**
 * An event of `GET /api/events` as it goes over the connection: `event` is
 * its name there and `data` what it carries, as JSON.
 *
 * Events are notices: one says what changed, and the browser loads what it
 * shows of that anew.
 *
 * - `hello`: the connection is up, and what is loaded from now on misses
 *   nothing.
 * - `resync`: the server cannot say what the browser missed; load everything
 *   anew.
 * - `articles`: a feed got new articles.
 * - `updated`: articles of a feed were changed by their publisher and have a
 *   new version.
 * - `feed`: a feed cannot be fetched any more (`error` says why) or can
 *   again (`error` is null).
 * - `reading`: what the account has read or starred changed.
 * - `tree`: folders or subscriptions changed.
 * - `labels`, `settings`: they changed.
 * - `rules`: filter rules changed. They hide articles and mark them as read,
 *   so the unread counts may have changed with them.
 * - `session`: a session of the account ended.
 * - `apps`: app passwords were made or revoked, or an app logged in with one
 *   for the first time.
 *
 * `by` is the name the tab that made the change gave itself in the header
 * `X-Rueder-Tab`, if it did, so that a tab knows its own change when it
 * comes back.
 */
export type ServerEvent =
	| {
		"event": "hello",
		"data": Record<symbol, never>,
	}
	| {
		"event": "resync",
		"data": Record<symbol, never>,
	}
	| {
		"event": "articles",
		"data": {
			feed_id: number,
			/**
			 * The number of the feed's newest article now.
			 */
			last_seq: number,
			/**
			 * How many came.
			 */
			new: number,
		},
	}
	| {
		"event": "updated",
		"data": {
			feed_id: number,
			count: number,
		},
	}
	| {
		"event": "feed",
		"data": {
			feed_id: number,
			error: string | null,
		},
	}
	| {
		"event": "reading",
		"data": {
			/**
			 * The feed's numbers after the change, if it was about one feed.
			 */
			feed: FeedUnread | null,
			/**
			 * The article's number in the feed, if it was about one article.
			 */
			seq: number | null,
			by: string | null,
		},
	}
	| {
		"event": "tree",
		"data": {
			by: string | null,
		},
	}
	| {
		"event": "labels",
		"data": {
			by: string | null,
		},
	}
	| {
		"event": "settings",
		"data": {
			by: string | null,
		},
	}
	| {
		"event": "rules",
		"data": {
			by: string | null,
		},
	}
	| {
		"event": "session",
		"data": {
			by: string | null,
		},
	}
	| {
		"event": "apps",
		"data": {
			by: string | null,
		},
	};

/**
 * A subscription's numbers.
 */
export type FeedUnread = {
	feed_id: number,
	/**
	 * The number of the feed's newest article.
	 */
	last_seq: number,
	read_upto: number,
	unread: number,
};

/**
 * How this rueder was built and where it runs.
 *
 * Part of what `GET /api/status` answers, for admins only.
 */
export type BuildInfo = {
	/**
	 * The version of the crate.
	 */
	version: string,
	/**
	 * The commit it was built from; empty where there was no git directory.
	 */
	commit: string,
	/**
	 * The branch that commit was on.
	 */
	branch: string,
	/**
	 * The tag on that commit, if it has one.
	 */
	tag: string,
	/**
	 * Something was changed and not committed when this was built.
	 */
	dirty: boolean,
	/**
	 * When it was built, as `2026-11-13T09:12:00Z`.
	 */
	built_at: string,
	/**
	 * The machine it was built for, as `x86_64-unknown-linux-gnu`.
	 */
	target: string,
	/**
	 * `release` or `debug`, and how hard the compiler tried (`3`, `z`, `0`).
	 */
	profile: string,
	opt_level: string,
	/**
	 * The run of the CI that built it, as an address; empty for a build by hand.
	 */
	ci_run: string,
	/**
	 * It runs in a container, as the image of the project does.
	 */
	container: boolean,
};

/**
 * What `GET /api/status` answers, for admins only.
 */
export type ServerStatus = {
	/**
	 * The version of the server.
	 */
	version: string,
	/**
	 * What this build is: commit, branch, when and how it was built.
	 */
	build: BuildInfo,
	started_at: string,
	uptime_s: number,
	/**
	 * The memory the server holds, if the system says.
	 */
	memory_bytes: number | null,
	/**
	 * What looks like a bottleneck or a problem, the most pressing first.
	 */
	hints: Array<StatusHint>,
	counts: StatusCounts,
	requests: StatusRequests,
	database: StatusDatabase,
	fetcher: StatusFetcher,
	finder: StatusFinder,
	images: StatusImages,
	problems: StatusProblems,
	/**
	 * Errors in the browsers of readers who agreed to send them.
	 */
	browsers: StatusBrowserErrors,
	/**
	 * Feeds readers reported, with their address: the one place the status
	 * names feeds, as the admins have to look at them. Never who reported.
	 */
	reported: Array<ReportedFeed>,
};

/**
 * How long things took in the last hour, in milliseconds. The times are null
 * when nothing was timed.
 */
export type Durations = {
	count: number,
	mean_ms: number | null,
	p50_ms: number | null,
	p95_ms: number | null,
	max_ms: number | null,
};

/**
 * Why fetches fail.
 */
export type FetchFailure = "status" | "timeout" | "blocked" | "dns" | "network" | "too_large" | "redirects" | "unreadable" | "other";

/**
 * What kind of error a report is about.
 */
export type ReportKind = "error" | "rejection" | "component" | "request";

export type StatusBrowserError = {
	kind: ReportKind,
	message: string,
	stack: string,
	/**
	 * How often it happened, in all browsers.
	 */
	count: number,
	/**
	 * In how many accounts.
	 */
	accounts: number,
	/**
	 * The versions of the frontend and the browsers it happened in.
	 */
	versions: Array<string>,
	browsers: Array<string>,
	first: string,
	last: string,
};

/**
 * The errors in browsers, for the status page.
 */
export type StatusBrowserErrors = {
	/**
	 * Whether the server takes reports at all.
	 */
	available: boolean,
	/**
	 * How many accounts send reports.
	 */
	consenting: number,
	/**
	 * The errors, the one that happened last first. No account is named.
	 */
	errors: Array<StatusBrowserError>,
};

/**
 * How much there is.
 */
export type StatusCounts = {
	accounts: number,
	feeds: number,
	/**
	 * Feeds somebody subscribes to, which are the ones fetched.
	 */
	subscribed_feeds: number,
	/**
	 * About how many articles: what PostgreSQL estimates.
	 */
	articles: number,
	/**
	 * Open streams of events: about how many tabs are open.
	 */
	live_connections: number,
};

/**
 * The database.
 */
export type StatusDatabase = {
	/**
	 * The connections of the server: open, idle, at most.
	 */
	pool_size: number,
	pool_idle: number,
	pool_max: number,
	/**
	 * All connections to the database, the server's and others'.
	 */
	connections: number,
	size_bytes: number,
	/**
	 * The share of blocks found in memory, since the statistics began.
	 */
	cache_hit_ratio: number | null,
	deadlocks: number,
	/**
	 * The query that has been running longest, in seconds.
	 */
	longest_query_s: number | null,
	tables: Array<StatusTable>,
};

export type StatusFailing = {
	failure: FetchFailure,
	/**
	 * The status the site answered with, for `status`.
	 */
	status: number | null,
	feeds: number,
};

/**
 * How fast feeds are fetched (`FETCH_ROUND`, `FETCH_AT_ONCE`, `FETCH_EVERY`).
 */
export type StatusFetchPace = {
	round: number,
	at_once: number,
	every_s: number,
	/**
	 * The most fetches an hour can have at this pace.
	 */
	per_hour: number,
};

/**
 * Fetching feeds.
 */
export type StatusFetcher = {
	/**
	 * Whether the server fetches feeds at all.
	 */
	running: boolean,
	/**
	 * The pace it fetches at, where it does.
	 */
	pace: StatusFetchPace | null,
	/**
	 * How many fetches the last hour had, of all kinds.
	 */
	per_hour: number,
	/**
	 * How long the feed that has waited longest past its time has waited, in
	 * seconds; 0 when none is due.
	 */
	behind_s: number,
	last_round_at: string | null,
	last_round_feeds: number | null,
	last_round_s: number | null,
	/**
	 * The fetches of the last hour.
	 */
	took: Durations,
	fetched: number,
	unchanged: number,
	failed: number,
	/**
	 * Fetches that failed at the database.
	 */
	broken: number,
	new_articles: number,
	/**
	 * Feeds whose last fetch failed, by why.
	 */
	failing: Array<StatusFailing>,
	/**
	 * Feeds fetched more than ten minutes after they were due.
	 */
	overdue: number,
	most_overdue_s: number | null,
	/**
	 * Feeds not fetched yet at all.
	 */
	waiting: number,
};

/**
 * The feed search, in the last hour.
 */
export type StatusFinder = {
	/**
	 * Whether the server looks at addresses at all.
	 */
	on: boolean,
	took: Durations,
	found: number,
	none: number,
	failed: number,
	limited: number,
};

/**
 * Something on the status page that wants looking at.
 */
export type StatusHint =
	| {
		"kind": "slow_route",
		route: string,
		p95_ms: number,
	}
	| {
		"kind": "server_errors",
		route: string,
		count: number,
	}
	| {
		"kind": "pool_busy",
		size: number,
	}
	| {
		"kind": "fetch_backlog",
		overdue: number,
		most_overdue_s: number,
	}
	| {
		"kind": "fetch_pace_full",
		per_hour: number,
	}
	| {
		"kind": "feeds_failing",
		failing: number,
		subscribed: number,
	}
	| {
		"kind": "not_fetching",
	}
	| {
		"kind": "cache_misses",
		hit_ratio: number,
	}
	| {
		"kind": "long_query",
		seconds: number,
	}
	| {
		"kind": "image_cache_full",
		percent: number,
	}
	| {
		"kind": "errors",
		count: number,
	}
	| {
		"kind": "limited",
		count: number,
	}
	| {
		"kind": "browser_errors",
		errors: number,
	}
	| {
		"kind": "reported_feeds",
		feeds: number,
	};

/**
 * The image proxy.
 */
export type StatusImages = {
	on: boolean,
	cache_bytes: number,
	cache_max_bytes: number,
	/**
	 * Sources left alone for now because they failed.
	 */
	failing_sources: number,
	/**
	 * Images not in the cache, in the last hour.
	 */
	took: Durations,
	cached: number,
	fetched: number,
	not_found: number,
	source_failed: number,
	not_image: number,
	too_large: number,
};

export type StatusProblem = {
	error: boolean,
	/**
	 * Where in the server it comes from, such as "rueder::fetch".
	 */
	target: string,
	text: string,
	count: number,
	first: string,
	last: string,
};

/**
 * The warnings and errors of the log.
 */
export type StatusProblems = {
	errors_last_hour: number,
	warnings_last_hour: number,
	/**
	 * The latest first. The same text from the same place is one.
	 */
	recent: Array<StatusProblem>,
};

/**
 * The requests of the last hour.
 */
export type StatusRequests = {
	all: Durations,
	/**
	 * Answers by their first digit: 1xx to 5xx.
	 */
	answers: [number,
	number,
	number,
	number,
	number],
	/**
	 * Answers that said "too many requests".
	 */
	limited: number,
	/**
	 * The routes, the slowest first by their 95th percentile.
	 */
	routes: Array<StatusRoute>,
};

export type StatusRoute = {
	/**
	 * The method and the route, such as "GET /api/feeds/{id}/articles".
	 */
	route: string,
	took: Durations,
	/**
	 * Answers with an error of the server.
	 */
	errors: number,
};

export type StatusTable = {
	name: string,
	/**
	 * With its indexes and, for a table in parts, all of them.
	 */
	bytes: number,
	/**
	 * What PostgreSQL estimates.
	 */
	rows: number,
};

/**
 * What `GET /api/reports/consent` answers.
 */
export type ReportsConsent = {
	/**
	 * Whether this server takes reports at all.
	 */
	available: boolean,
	/**
	 * Whether this account sends them.
	 */
	on: boolean,
};

/**
 * What `PUT /api/reports/consent` reads. Off deletes what the account sent.
 */
export type ReportsConsentChange = {
	on: boolean,
};

/**
 * What `POST /api/reports` reads: at most twenty reports. It answers 204.
 */
export type ClientReports = {
	reports: Array<ClientReport>,
};

/**
 * One error, as the browser saw it.
 */
export type ClientReport = {
	kind: ReportKind,
	message: string,
	/**
	 * The lines of the stack in the files of rueder's frontend, as
	 * "_app/immutable/chunks/x.js:12:34", one a line.
	 */
	stack?: string,
	/**
	 * The version of the frontend.
	 */
	version: string,
	/**
	 * The browser and its major version, such as "Firefox 140".
	 */
	browser: string,
};

/**
 * An account as a file, for another rueder. `GET /api/export` answers with
 * it, and `POST /api/import` reads it.
 */
export type AccountExport = {
	/**
	 * Always "rueder-account".
	 */
	format: string,
	/**
	 * The layout of the file, 1. A server reads only the layouts it knows.
	 */
	version: number,
	exported_at: string,
	/**
	 * The settings of the interface, as `GET /api/settings` gives them.
	 */
	settings: Record<string, unknown>,
	/**
	 * Folders and feeds from the top down, in their order: a folder before
	 * what is in it.
	 */
	tree: Array<ExportedNode>,
	labels: Array<ExportedLabel>,
	/**
	 * The filter rules in their order.
	 */
	rules: Array<ExportedRule>,
};

/**
 * An article, as it can be found on another server.
 */
export type ArticleRef = {
	/**
	 * Its number in its feed on the server the file comes from; with the
	 * feed's number its id in that server's API.
	 */
	seq: number,
	/**
	 * Its id in its feed, as the feed gives it.
	 */
	guid: string,
	/**
	 * Its page.
	 */
	url: string | null,
	published_at: string,
};

/**
 * Who a feed is fetched as.
 */
export type ExportedAgent = "rueder" | "browser";

/**
 * An article the reader did something with.
 */
export type ExportedArticle = {
	seq: number,
	guid: string,
	url: string | null,
	published_at: string,
	title: string,
	/**
	 * Whether it is read, whatever the mark says.
	 */
	read: boolean,
	starred: boolean,
	/**
	 * The names of its labels.
	 */
	labels: Array<string>,
};

/**
 * A subscription, with what the reader did in it.
 */
export type ExportedFeed = {
	/**
	 * The feed's number on the server the file comes from.
	 */
	id: number,
	/**
	 * The address of the feed: how it is found again.
	 */
	url: string,
	site_url: string | null,
	/**
	 * The feed's own title.
	 */
	title: string,
	/**
	 * The name the reader gave it.
	 */
	own_title: string | null,
	/**
	 * The folder it is in, by its path; empty at the top.
	 */
	folder: Array<string>,
	agent: ExportedAgent,
	/**
	 * The number of the newest article on the server the file comes from.
	 */
	last_seq: number,
	/**
	 * The article the mark stands at: it and everything before it is read,
	 * but for the articles below that say otherwise. None if the mark is at
	 * the start.
	 */
	read_upto: ArticleRef | null,
	/**
	 * The articles that are read above the mark or unread below it, starred
	 * or labelled.
	 */
	articles: Array<ExportedArticle>,
};

export type ExportedLabel = {
	title: string,
	color: string,
};

/**
 * A folder or a feed of the tree.
 */
export type ExportedNode =
	| {
		"kind": "folder",
		path: Array<string>,
	}
	| {
		"kind": "feed",
	} & ExportedFeed;

export type ExportedRule = {
	enabled: boolean,
	scope: ExportedScope,
	field: RuleField,
	match: RuleMatch,
	pattern: string,
	action: RuleAction,
};

/**
 * Where a rule holds: a folder by its path, a feed by its address.
 */
export type ExportedScope =
	| {
		"kind": "all",
	}
	| {
		"kind": "folder",
		path: Array<string>,
	}
	| {
		"kind": "feed",
		url: string,
	};

/**
 * What an import did. `POST /api/import` answers with it.
 */
export type AccountImported = {
	/**
	 * Feeds the account reads now and did not before.
	 */
	feeds: number,
	/**
	 * Feeds of the file the account read already.
	 */
	known: number,
	/**
	 * Folders that were made.
	 */
	folders: number,
	/**
	 * Articles of the file that were found here.
	 */
	articles: number,
	/**
	 * Articles that were not found: what was read, starred or labelled of
	 * them is lost.
	 */
	missing: number,
	/**
	 * Labels that were made.
	 */
	labels: number,
	/**
	 * Rules that were added.
	 */
	rules: number,
	/**
	 * What the file has that could not be taken: feeds without an address
	 * that can be fetched, articles without an id, labels and rules that
	 * break the rules, rules whose folder or feed is not there.
	 */
	skipped: number,
	/**
	 * Whether the settings came with it.
	 */
	settings: boolean,
};
